function isPlainObject(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function hasOwn(value, key) {
  return Object.prototype.hasOwnProperty.call(value, key);
}

function nonEmptyString(value) {
  return typeof value === 'string' && value.trim().length > 0;
}

function uniqueTrimmedStrings(value) {
  if (!Array.isArray(value)) return [];
  return Array.from(new Set(value.map((item) => typeof item === 'string' ? item.trim() : '').filter(Boolean)));
}

function isSafeRepoRelativePath(value) {
  if (!nonEmptyString(value)) return false;
  const path = value.trim();
  if (path.startsWith('/') || path.startsWith('./') || path.endsWith('/')) return false;
  if (path.includes('\\') || path.includes('\0') || path.includes('//')) return false;
  const parts = path.split('/');
  return !parts.some((part) => part === '' || part === '.' || part === '..');
}

function escapeRegex(value) {
  return value.replace(/[.+^${}()|[\]\\]/g, '\\$&');
}

function globToRegex(glob) {
  let pattern = '';
  for (let index = 0; index < glob.length; index += 1) {
    const char = glob[index];
    if (char === '*' && glob[index + 1] === '*') {
      pattern += '.*';
      index += 1;
    } else if (char === '*') {
      pattern += '[^/]*';
    } else if (char === '?') {
      pattern += '[^/]';
    } else {
      pattern += escapeRegex(char);
    }
  }
  return new RegExp('^' + pattern + '$', 'i');
}

function forbiddenRuleMatches(path, rawRule) {
  const rule = String(rawRule || '').trim().replace(/\\/g, '/');
  if (!rule) return false;
  if (rule.includes('/') || /[*?]/.test(rule)) {
    return globToRegex(rule).test(path);
  }
  const compactPath = path.toLowerCase().replace(/[^a-z0-9]+/g, '');
  const compactRule = rule.toLowerCase().replace(/[^a-z0-9]+/g, '');
  return compactRule.length >= 4 && compactPath.includes(compactRule);
}

function stableValue(value) {
  if (Array.isArray(value)) {
    return value.map(stableValue);
  }
  if (isPlainObject(value)) {
    const result = {};
    for (const key of Object.keys(value).sort()) {
      result[key] = stableValue(value[key]);
    }
    return result;
  }
  return value;
}

function stableStringify(value) {
  return JSON.stringify(stableValue(value));
}

function fnv1a32(value) {
  let hash = 0x811c9dc5;
  for (let index = 0; index < value.length; index += 1) {
    hash ^= value.charCodeAt(index);
    hash = Math.imul(hash, 0x01000193);
  }
  return (hash >>> 0).toString(16).padStart(8, '0');
}

function deriveExecutionRequestId(candidate, approvedFileScope) {
  const identity = {
    repository_full_name: candidate.repository_full_name.trim(),
    task_id: candidate.task_id.trim(),
    branch_name: candidate.branch_name.trim(),
    base_ref: 'origin/main',
    approved_file_scope: [...approvedFileScope].sort()
  };
  return 'route_b_exec_' + fnv1a32(stableStringify(identity));
}

function validatePathBeforeWrite(path, approvedFileScope, forbiddenFileScope) {
  if (!approvedFileScope.includes(path)) {
    return 'requested_changed_path_outside_approved_file_scope:' + path;
  }
  if (!isSafeRepoRelativePath(path)) {
    return 'requested_changed_path_invalid_repo_relative_path:' + path;
  }
  if (forbiddenFileScope.some((rule) => forbiddenRuleMatches(path, rule))) {
    return 'requested_changed_path_intersects_forbidden_file_scope:' + path;
  }
  return null;
}

const ALLOWED_GITHUB_ACTIONS = [
  'create_branch',
  'create_or_update_approved_files',
  'open_pull_request',
  'read_ci_status'
];

const ALLOWED_FILE_OPERATIONS = [
  'create',
  'update'
];

const TERMINAL_STATUSES = [
  'blocked',
  'failed',
  'pr_opened',
  'ci_failed',
  'ci_passed',
  'smoke_validated'
];

const REQUIRED_FALSE_FLAGS = [
  'runtime_allowed',
  'broker_execution_allowed',
  'live_trading_allowed',
  'direct_main_write_allowed',
  'force_push_allowed',
  'file_delete_allowed',
  'n8n_merge_allowed',
  'executor_merge_allowed',
  'production_secret_access_allowed',
  'server_apply_allowed',
  'pm_l2_approval_claimed'
];

const input = $input.first().json || {};
const envelope = isPlainObject(input.body) ? input.body : input;
const upstreamAccepted = envelope.accepted === true && envelope.validation_status === 'pass';
const rawRequestPresent = hasOwn(envelope, 'github_execution_request_json');
const request = envelope.normalized_github_execution_request_json;
const errors = [];

if (!upstreamAccepted) {
  errors.push('validated_normalized_github_execution_request_required');
}

if (rawRequestPresent) {
  errors.push('raw_github_execution_request_json_forbidden');
}

if (!isPlainObject(request)) {
  errors.push('normalized_github_execution_request_json_must_be_object');
}

const candidate = isPlainObject(request) ? request : {};
const smokeOnly = candidate.smoke_only === true;

if (!nonEmptyString(candidate.repository_full_name)) {
  errors.push('repository_full_name_required');
} else if (candidate.repository_full_name.trim() !== 'Viktoryyyyy/moex-robot') {
  errors.push('repository_full_name_not_allowed');
}

if (!nonEmptyString(candidate.task_id)) {
  errors.push('task_id_required_for_idempotency');
}

if (!nonEmptyString(candidate.branch_name)) {
  errors.push('branch_name_required');
} else {
  const branchName = candidate.branch_name.trim();
  if (branchName.startsWith('route-b/')) {
    errors.push('route_b_branch_prefix_forbidden');
  }
  if (!/^n8n\/[A-Za-z0-9][A-Za-z0-9._/-]*$/.test(branchName)) {
    errors.push('branch_name_must_use_n8n_prefix');
  }
  if (branchName.includes('..') || branchName.includes('//') || branchName.endsWith('/')) {
    errors.push('branch_name_invalid');
  }
  if (['main', 'master', 'refs/heads/main', 'refs/heads/master'].includes(branchName.toLowerCase())) {
    errors.push('branch_name_direct_main_or_master_forbidden');
  }
}

if (!nonEmptyString(candidate.base_ref)) {
  errors.push('base_ref_required');
} else if (candidate.base_ref.trim() !== 'origin/main') {
  errors.push('base_ref_must_equal_origin_main');
}

let approvedFileScope = [];
if (!Array.isArray(candidate.approved_file_scope)) {
  errors.push('approved_file_scope_must_be_array');
} else {
  approvedFileScope = uniqueTrimmedStrings(candidate.approved_file_scope);
  if (approvedFileScope.length !== candidate.approved_file_scope.length) {
    errors.push('approved_file_scope_must_contain_unique_non_empty_strings');
  }
  for (const path of approvedFileScope) {
    if (!isSafeRepoRelativePath(path)) {
      errors.push('approved_file_scope_invalid_repo_relative_path:' + path);
    }
  }
  if (smokeOnly && approvedFileScope.length !== 0) {
    errors.push('smoke_only_approved_file_scope_must_be_empty');
  }
  if (!smokeOnly && approvedFileScope.length === 0) {
    errors.push('approved_file_scope_must_not_be_empty_before_mutation');
  }
}

let forbiddenFileScope = [];
if (!Array.isArray(candidate.forbidden_file_scope)) {
  errors.push('forbidden_file_scope_must_be_array');
} else {
  forbiddenFileScope = uniqueTrimmedStrings(candidate.forbidden_file_scope);
  if (forbiddenFileScope.length === 0) {
    errors.push('forbidden_file_scope_must_not_be_empty');
  }
  if (forbiddenFileScope.length !== candidate.forbidden_file_scope.length) {
    errors.push('forbidden_file_scope_must_contain_unique_non_empty_strings');
  }
}

for (const path of approvedFileScope) {
  if (forbiddenFileScope.some((rule) => forbiddenRuleMatches(path, rule))) {
    errors.push('approved_file_scope_intersects_forbidden_file_scope:' + path);
  }
}

const requestedChangedPaths = approvedFileScope.slice();
for (const path of requestedChangedPaths) {
  const writePathError = validatePathBeforeWrite(path, approvedFileScope, forbiddenFileScope);
  if (writePathError) errors.push(writePathError);
}

if (candidate.merge_authority !== 'PM_L2_ONLY') {
  errors.push('merge_authority_must_equal_PM_L2_ONLY');
}

if (candidate.server_apply_authority !== 'PM_L2_ONLY_OR_EXPLICIT_PM_L2_TASK') {
  errors.push('server_apply_authority_must_equal_PM_L2_ONLY_OR_EXPLICIT_PM_L2_TASK');
}

for (const flag of REQUIRED_FALSE_FLAGS) {
  if (!hasOwn(candidate, flag)) {
    errors.push(flag + '_required_false');
  } else if (candidate[flag] !== false) {
    errors.push(flag + '_must_be_false');
  }
}

if (candidate.ci_required !== true) {
  errors.push('ci_required_must_be_true');
}

if (!nonEmptyString(candidate.expected_ci_workflow)) {
  errors.push('expected_ci_workflow_required');
} else if (candidate.expected_ci_workflow.trim() !== 'tests') {
  errors.push('expected_ci_workflow_must_equal_tests');
}

const accepted = errors.length === 0;
const executionRequestId = accepted
  ? deriveExecutionRequestId(candidate, approvedFileScope)
  : null;

const normalizedRequest = accepted ? {
  repository_full_name: candidate.repository_full_name.trim(),
  lane: nonEmptyString(candidate.lane) ? candidate.lane.trim() : null,
  task_id: candidate.task_id.trim(),
  requested_by_role: nonEmptyString(candidate.requested_by_role) ? candidate.requested_by_role.trim() : null,
  execution_mode: nonEmptyString(candidate.execution_mode) ? candidate.execution_mode.trim() : null,
  execution_request_id: executionRequestId,
  branch_name: candidate.branch_name.trim(),
  base_ref: 'origin/main',
  approved_file_scope: approvedFileScope,
  requested_changed_paths: requestedChangedPaths,
  approved_file_scope_is_exact_requested_scope: true,
  forbidden_file_scope: forbiddenFileScope,
  merge_authority: 'PM_L2_ONLY',
  server_apply_authority: 'PM_L2_ONLY_OR_EXPLICIT_PM_L2_TASK',
  runtime_allowed: false,
  broker_execution_allowed: false,
  live_trading_allowed: false,
  direct_main_write_allowed: false,
  force_push_allowed: false,
  file_delete_allowed: false,
  n8n_merge_allowed: false,
  executor_merge_allowed: false,
  production_secret_access_allowed: false,
  server_apply_allowed: false,
  pm_l2_approval_claimed: false,
  ci_required: true,
  expected_ci_workflow: 'tests',
  smoke_only: smokeOnly
} : null;

const mutationManifest = accepted && !smokeOnly
  ? requestedChangedPaths.map((path, index) => ({
      sequence: index + 1,
      path,
      operation_resolution: {
        source: 'github_path_existence_at_pinned_base_sha',
        when_absent: 'create',
        when_present: 'update',
        allowed_operations: ALLOWED_FILE_OPERATIONS,
        explicit_operation_required_before_write: true
      },
      before_each_write_guards: {
        validator: 'validatePathBeforeWrite',
        path_must_be_in_approved_file_scope: true,
        path_must_be_outside_forbidden_file_scope: true,
        delete_operation_rejected: true
      }
    }))
  : [];

const idempotencyPolicy = accepted ? {
  execution_request_id: executionRequestId,
  key_source: 'deterministic_hash_of_normalized_request_identity',
  lookup_required_before_any_mutation: true,
  durable_state_store_required: true,
  replay_same_key: 'resume_from_recorded_step_or_return_existing_terminal_result',
  duplicate_commit_allowed: false,
  duplicate_pull_request_allowed: false,
  existing_branch: {
    same_execution_request_id: 'reuse',
    different_execution_request_id: 'blocked',
    force_update_allowed: false
  },
  existing_pull_request: {
    matching_open_pr: 'reuse',
    multiple_matching_open_prs: 'blocked',
    closed_or_merged_pr: 'return_existing_terminal_result_or_blocked'
  }
} : null;

const terminalResultContract = {
  schema_version: 'github_executor_execution_result.v0.1',
  required_fields: [
    'execution_request_id',
    'status',
    'repository_full_name',
    'base_ref',
    'base_sha',
    'feature_branch',
    'implementation_commit_sha',
    'pr_number',
    'pr_url',
    'pr_head_sha',
    'ci_workflow',
    'ci_run_id',
    'ci_conclusion',
    'requested_file_count',
    'applied_file_count',
    'all_requested_files_applied',
    'approved_for_merge',
    'merge_performed',
    'error'
  ],
  allowed_statuses: TERMINAL_STATUSES,
  mutation_result_required_non_null_fields: [
    'feature_branch',
    'implementation_commit_sha',
    'pr_number',
    'pr_url',
    'pr_head_sha'
  ],
  rules: {
    blocked_or_failed_requires_error_object: true,
    partial_multi_file_apply_must_be_failed: true,
    partial_multi_file_apply_can_report_success: false,
    success_requires_applied_file_count_equals_requested_file_count: true,
    success_requires_all_requested_files_applied: true,
    pr_head_sha_must_equal_implementation_commit_sha: true,
    ci_passed_does_not_imply_merge_approval: true,
    approved_for_merge_must_be_false: true,
    merge_performed_must_be_false: true
  }
};

const executionPath = accepted
  ? (smokeOnly
      ? {
          execution_mode: 'smoke_validation_only',
          github_actions: [],
          github_mutation_allowed: false,
          github_mutation_performed: false,
          empty_approved_file_scope_required: true,
          branch_creation_allowed: false,
          commit_creation_allowed: false,
          pull_request_creation_allowed: false,
          steps: [
            {
              sequence: 1,
              action: 'validate_normalized_request',
              read_only: true
            },
            {
              sequence: 2,
              action: 'derive_execution_request_id',
              read_only: true
            },
            {
              sequence: 3,
              action: 'emit_terminal_result',
              status: 'smoke_validated',
              read_only: true
            }
          ]
        }
      : {
          execution_mode: 'structural_definition_only',
          real_github_api_nodes_present: false,
          credentials_embedded: false,
          allowed_actions: ALLOWED_GITHUB_ACTIONS,
          base_pin_policy: {
            source: 'origin/main',
            resolve_once_before_mutation: true,
            reuse_same_pinned_base_sha_on_replay: true,
            stale_base_result: 'blocked'
          },
          idempotency_policy: idempotencyPolicy,
          file_batch_contract: {
            requested_changed_paths: requestedChangedPaths,
            requested_changed_paths_source: 'approved_file_scope_exact',
            approved_file_scope_is_exact_requested_scope: true,
            allowed_operations: ALLOWED_FILE_OPERATIONS,
            delete_operation_rejected: true,
            stage_all_files_before_commit: true,
            single_commit_for_batch: true,
            before_each_write_revalidation: true,
            partial_apply_success_allowed: false,
            partial_apply_terminal_status: 'failed',
            success_requires_applied_file_count_equals_requested_file_count: true
          },
          mutation_manifest: mutationManifest,
          steps: [
            {
              sequence: 1,
              action: 'preflight_and_pin_base',
              base_ref: 'origin/main',
              derive_execution_request_id: true,
              idempotency_lookup_required: true,
              read_only: true
            },
            {
              sequence: 2,
              action: 'create_branch',
              branch_name_source: 'branch_name',
              required_prefix: 'n8n/',
              existing_same_request: 'reuse',
              existing_different_request: 'blocked',
              force: false
            },
            {
              sequence: 3,
              action: 'create_or_update_approved_files',
              branch_source: 'branch_name',
              requested_changed_paths: requestedChangedPaths,
              mutation_manifest: mutationManifest,
              path_guard: 'approved_file_scope',
              forbidden_scope_guard: 'forbidden_file_scope',
              before_each_write_guard: 'validatePathBeforeWrite',
              allowed_file_operations: ALLOWED_FILE_OPERATIONS,
              delete_operation_rejected: true,
              stage_all_files_before_commit: true,
              single_commit_for_batch: true,
              partial_apply_success_allowed: false
            },
            {
              sequence: 4,
              action: 'open_pull_request',
              head_source: 'branch_name',
              base_branch: 'main',
              existing_matching_open_pr: 'reuse',
              duplicate_pull_request_allowed: false,
              merge_allowed: false
            },
            {
              sequence: 5,
              action: 'read_ci_status',
              workflow_source: 'expected_ci_workflow',
              read_only: true,
              ci_success_is_merge_approval: false
            },
            {
              sequence: 6,
              action: 'emit_terminal_result',
              contract_schema_version: 'github_executor_execution_result.v0.1',
              blocked_or_failed_on_error: true,
              partial_apply_reports_failed: true
            }
          ]
        })
  : null;

return [{
  json: {
    workflow_name: 'MOEX_ROUTE_B_GITHUB_EXECUTOR_EXECUTION_PATH_V0_1_TARGET',
    spec_version: 'github_executor_execution_path.v0.1',
    validation_status: accepted ? 'pass' : 'rejected',
    accepted,
    validation_errors: errors,
    execution_request_id: executionRequestId,
    revalidated_normalized_github_execution_request_json: normalizedRequest,
    execution_path: executionPath,
    terminal_result_contract: terminalResultContract,
    controls: {
      executor_action: 'structural_controlled_github_execution_path',
      structural_definition_only: true,
      normalized_intake_only: true,
      raw_github_execution_request_allowed: false,
      github_mutation_enabled: false,
      github_mutation_performed: false,
      real_github_api_nodes_present: false,
      credentials_embedded: false,
      direct_main_write_allowed: false,
      force_push_allowed: false,
      file_delete_allowed: false,
      merge_allowed: false,
      merge_performed: false,
      n8n_merge_allowed: false,
      executor_merge_allowed: false,
      server_apply_allowed: false,
      server_apply_performed: false,
      broker_execution_allowed: false,
      live_trading_allowed: false,
      runtime_allowed: false,
      production_secret_access_allowed: false,
      production_secret_accessed: false,
      pm_l2_approval_claimed: false,
      ci_success_is_merge_approval: false,
      smoke_empty_scope_mutation_allowed: false,
      duplicate_commit_allowed: false,
      duplicate_pull_request_allowed: false,
      partial_apply_success_allowed: false
    },
    next_step: accepted
      ? (smokeOnly
          ? 'return smoke_validated without branch, commit, or pull request mutation'
          : 'bind only the declared structural actions in a separately approved credentialed runtime implementation')
      : 'return terminal blocked result with validation_errors to PM_L3 or PM_L2'
  }
}];
